DO $$ DECLARE expected_table_count constant integer:=3; actual_tables text[]; columns_hash text; constraints_hash text; indexes_hash text; acl_hash text; trigger_hash text; function_hash text; effective_acl_hash text; BEGIN
IF current_setting('ai_mls.r3b1_advisory_artifact_sha256',true)<>'ae70f9c9b3b18b08eff3e2b0b8bbdb24c14b9ca6a6a980cfc1f320b9223bc6ac' THEN RAISE EXCEPTION 'advisory migration checksum mismatch'; END IF;
IF obj_description('app_advisory'::regnamespace,'pg_namespace')<>'REL002-R3B1-ADVISORY-V1|schema_version=1|contract_fingerprint=advisory-v1-3-tables' THEN RAISE EXCEPTION 'advisory schema_version contract_fingerprint mismatch'; END IF;
SELECT array_agg(tablename ORDER BY tablename) INTO actual_tables FROM pg_tables WHERE schemaname='app_advisory';
IF cardinality(actual_tables)<>expected_table_count OR actual_tables<>ARRAY['advisory_idempotency','advisory_prompts','advisory_records'] THEN RAISE EXCEPTION 'advisory unexpected table inventory mismatch'; END IF;
SELECT md5(string_agg(concat_ws('|',table_name,ordinal_position,column_name,data_type,udt_name,is_nullable,coalesce(column_default,'')),E'\n' ORDER BY table_name,ordinal_position)) INTO columns_hash FROM information_schema.columns WHERE table_schema='app_advisory';
SELECT md5(string_agg(concat_ws('|',r.relname,c.conname,c.contype,pg_get_constraintdef(c.oid,true)),E'\n' ORDER BY r.relname,c.conname)) INTO constraints_hash FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='app_advisory';
SELECT md5(string_agg(concat_ws('|',t.relname,i.relname,pg_get_indexdef(x.indexrelid)),E'\n' ORDER BY t.relname,i.relname)) INTO indexes_hash FROM pg_index x JOIN pg_class t ON t.oid=x.indrelid JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='app_advisory';
IF columns_hash<>'7dfd0b9b9df28e5872e143012c428092' OR constraints_hash<>'a2680ba17fd129ee99b229492ae7b1f0' OR indexes_hash<>'68b027127b2012e14df946552dd14121' THEN RAISE EXCEPTION 'advisory columns constraints indexes mismatch'; END IF;
IF pg_get_userbyid((SELECT nspowner FROM pg_namespace WHERE nspname='app_advisory'))<>'ai_mls_production_migration_operator' OR EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='app_advisory' AND tableowner<>'ai_mls_production_migration_operator') THEN RAISE EXCEPTION 'advisory ownership mismatch'; END IF;
SELECT md5(string_agg(concat_ws('|',r.relname,t.tgname,t.tgenabled,t.tgtype,pn.nspname,p.proname,pg_get_triggerdef(t.oid,true)),E'\n' ORDER BY r.relname,t.tgname)) INTO trigger_hash FROM pg_trigger t JOIN pg_class r ON r.oid=t.tgrelid JOIN pg_namespace n ON n.oid=r.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace WHERE n.nspname='app_advisory' AND NOT t.tgisinternal;
SELECT md5(string_agg(concat_ws('|',p.proname,l.lanname,pg_get_function_result(p.oid),trim(p.prosrc),pg_get_userbyid(p.proowner),p.prosecdef,coalesce(array_to_string(p.proconfig,','),'')),E'\n' ORDER BY p.proname)) INTO function_hash FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='app_advisory';
IF trigger_hash<>'9a8a4913e4d6cf49597204466c84c720' OR function_hash<>'c55bb1de5ccba2b1308a21316f1acaa0' THEN RAISE EXCEPTION 'advisory exact trigger/function topology mismatch'; END IF;
IF has_schema_privilege('ai_mls_production_runtime','app_advisory','CREATE') OR NOT has_schema_privilege('ai_mls_production_runtime','app_advisory','USAGE') THEN RAISE EXCEPTION 'advisory runtime schema ACL mismatch'; END IF;
IF EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='app_advisory' AND (NOT has_table_privilege('ai_mls_production_runtime',format('%I.%I',schemaname,tablename),'SELECT') OR has_table_privilege('ai_mls_production_runtime',format('%I.%I',schemaname,tablename),'DELETE,TRUNCATE,REFERENCES,TRIGGER'))) THEN RAISE EXCEPTION 'advisory runtime table ACL mismatch'; END IF;
SELECT md5(string_agg(concat_ws('|',table_name,privilege_type,is_grantable),E'\n' ORDER BY table_name,privilege_type)) INTO acl_hash FROM information_schema.role_table_grants WHERE table_schema='app_advisory' AND grantee='ai_mls_production_runtime';
IF acl_hash<>'fb9da767cf2d7c00b2da4b982a632f35' THEN RAISE EXCEPTION 'advisory exact runtime DML mismatch'; END IF;
SELECT md5(string_agg(concat_ws('|',t.tablename,has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'SELECT'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'INSERT'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'UPDATE'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'DELETE'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'TRUNCATE'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'REFERENCES'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'TRIGGER')),E'\n' ORDER BY t.tablename)) INTO effective_acl_hash FROM pg_tables t WHERE t.schemaname='app_advisory';
IF effective_acl_hash<>'42150fb07658a71077af24c0b8c9ba3b' THEN RAISE EXCEPTION 'advisory effective runtime ACL mismatch'; END IF;
IF EXISTS(SELECT 1 FROM pg_class r CROSS JOIN LATERAL aclexplode(coalesce(r.relacl,acldefault('r',r.relowner))) a WHERE r.relnamespace='app_advisory'::regnamespace AND r.relkind='r' AND (a.grantee NOT IN (r.relowner,(SELECT oid FROM pg_roles WHERE rolname='ai_mls_production_runtime')) OR (a.grantee=(SELECT oid FROM pg_roles WHERE rolname='ai_mls_production_runtime') AND a.is_grantable))) THEN RAISE EXCEPTION 'advisory PUBLIC leakage, unexpected grantee, or grant option'; END IF;
IF EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='app_advisory' AND (a.grantee NOT IN (n.nspowner,(SELECT oid FROM pg_roles WHERE rolname='ai_mls_production_runtime')) OR (a.grantee=(SELECT oid FROM pg_roles WHERE rolname='ai_mls_production_runtime') AND (a.privilege_type<>'USAGE' OR a.is_grantable)))) OR EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='app_advisory' AND a.grantee<>p.proowner) THEN RAISE EXCEPTION 'advisory schema/function ACL leakage'; END IF;
IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='app_advisory' AND p.proname='reject_append_only_mutation' AND pg_get_userbyid(p.proowner)='ai_mls_production_migration_operator' AND position('append-only' IN p.prosrc)>0)<>1 OR EXISTS(SELECT 1 FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='app_advisory' AND r.relkind='S') THEN RAISE EXCEPTION 'advisory function/sequence mismatch'; END IF;
IF EXISTS(SELECT 1 FROM pg_auth_members WHERE member IN (SELECT oid FROM pg_roles WHERE rolname IN ('ai_mls_production_runtime','ai_mls_production_migration_operator'))) OR EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles granted ON granted.oid=m.roleid JOIN pg_roles member_role ON member_role.oid=m.member WHERE granted.rolname IN ('ai_mls_production_runtime','ai_mls_production_migration_operator') AND member_role.rolname<>'postgres') THEN RAISE EXCEPTION 'advisory unexpected role membership'; END IF;
END $$;
